import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif
from sklearn.preprocessing import StandardScaler

MAX_DRIVERS = 3

def design(feats):
    # Identify strong univariate predictors (p < 0.05)
    strong_features = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] in ('copy_number', 'expression'):
            t_stat, p_val = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i])
            if p_val < 0.05:
                strong_features.append((fid, abs(t_stat)))

    # Sort by effect size
    strong_features.sort(key=lambda x: x[1], reverse=True)

    # Check for product terms among top candidates
    top_fids = [f[0] for f in strong_features[:8]]

    # Look for correlated pairs that might suggest interaction
    candidates = []
    for i in range(len(top_fids)):
        for j in range(i+1, len(top_fids)):
            fid_a, fid_b = top_fids[i], top_fids[j]
            col_a = feats.column(fid_a)
            col_b = feats.column(fid_b)

            # Compute correlation
            corr = np.corrcoef(feats.x[:, col_a], feats.x[:, col_b])[0,1]
            if abs(corr) >= 0.6:
                # Add product term
                candidates.append((fid_a, fid_b))

    # If we have product candidates, select best one
    if candidates:
        # Use mutual information to rank product terms
        best_pair = None
        best_mi = -1

        for a, b in candidates:
            col_a = feats.column(a)
            col_b = feats.column(b)
            prod = feats.x[:, col_a] * feats.x[:, col_b]
            mi = mutual_info_classif(prod.reshape(-1,1), feats.y)[0]
            if mi > best_mi:
                best_mi = mi
                best_pair = (a, b)

        if best_pair and best_mi > 0.01:  # threshold for meaningful interaction
            return Design(
                drivers=(best_pair[0], best_pair[1]),
                columns=(best_pair[0], best_pair[1]),
                products=(best_pair,),
                loadings={best_pair[0]: 1.0, best_pair[1]: 1.0}
            )

    # Fall back to single strongest predictor if no interaction found
    if strong_features:
        main_driver = strong_features[0][0]
        return Design(
            drivers=(main_driver,),
            columns=(main_driver,),
            products=(),
            loadings={main_driver: 1.0}
        )

    # No mechanism found
    return Design(
        drivers=(),
        columns=(),
        products=(),
        loadings={}
    )

